buildGradleAdditions.insert:
repositories {
    google()
    mavenCentral()
}
dependencies {
    implementation('com.google.ads.mediation:applovin') {
        version {
            strictly '13.6.4.0'
        }
    }
}

gameActivityClassAdditions.insert:
public boolean AndroidThunkJava_ApplyOpenMobileAdsAdMobAppLovinConsentSignals(
    final boolean applyGdpr,
    final boolean hasUserConsent,
    final boolean applyUsPrivacy,
    final boolean doNotSell
)
{
    try
    {
        if (applyGdpr)
        {
            com.applovin.sdk.AppLovinPrivacySettings.setHasUserConsent(
                hasUserConsent,
                GameActivity.this
            );
            if (!com.applovin.sdk.AppLovinPrivacySettings.isUserConsentSet(GameActivity.this)
                || com.applovin.sdk.AppLovinPrivacySettings.hasUserConsent(GameActivity.this)
                    != hasUserConsent)
            {
                return false;
            }
        }
        if (applyUsPrivacy)
        {
            com.applovin.sdk.AppLovinPrivacySettings.setDoNotSell(
                doNotSell,
                GameActivity.this
            );
            if (!com.applovin.sdk.AppLovinPrivacySettings.isDoNotSellSet(GameActivity.this)
                || com.applovin.sdk.AppLovinPrivacySettings.isDoNotSell(GameActivity.this)
                    != doNotSell)
            {
                return false;
            }
        }
        return true;
    }
    catch (Exception exception)
    {
        return false;
    }
}
